local NailMaker = {}
local PRODUCTS = {
    nails = { name = "Žebelj", ironCost = 1, time = 1, cost = 5, quantity = 20, description = "Železni žeblji." },
    hinges = { name = "Tečaj", ironCost = 3, time = 3, cost = 30, description = "Vratni tečaji." },
    brackets = { name = "Nosilci", ironCost = 5, time = 4, cost = 50, description = "Nosilni nosilci." },
    grilles = { name = "Rešetke", ironCost = 8, time = 7, cost = 100, securityBonus = 10, description = "Okenske rešetke." },
    locks = { name = "Rezalne ključavnice", ironCost = 4, time = 5, cost = 60, securityBonus = 15, description = "Preproste ključavnice." },
    decorative_fittings = { name = "Okrasni okovji", ironCost = 3, copperCost = 2, time = 6, cost = 80, prestige = 5, description = "Okrasni kovinski okovji." },
}
local BUILDINGS = {
    workshop = { name = "Žebeljarna", cost = { gold = 200, wood = 100, iron = 50 }, upkeep = 8, qualityBonus = 5 },
    nailery = { name = "Žebeljnica", cost = { gold = 600, wood = 200, stone = 100, iron = 100 }, upkeep = 15, qualityBonus = 15 },
    hardware_shop = { name = "Železnina", cost = { gold = 1200, wood = 200, stone = 300, iron = 150 }, upkeep = 30, qualityBonus = 20 },
    royal_hardware = { name = "Kraljevska železnina", cost = { gold = 4000, wood = 400, stone = 800, iron = 300 }, upkeep = 80, qualityBonus = 35, prestigeBonus = 15 },
}
NailMaker.ironStock = 20; NailMaker.copperStock = 5; NailMaker.productStock = {}; NailMaker.buildings = {}; NailMaker.nailMaker = nil; NailMaker.activeMaking = {}; NailMaker.totalProducts = 0; NailMaker.dayTimer = 0
function NailMaker.init() NailMaker.ironStock=20; NailMaker.copperStock=5; NailMaker.productStock={}; NailMaker.buildings={}; NailMaker.nailMaker=nil; NailMaker.activeMaking={}; NailMaker.totalProducts=0; NailMaker.dayTimer=0; print("[NailMaker] Royal Nail Maker & Hardware System initialized (6 products, 4 buildings)") end
function NailMaker.hireNailMaker(n,s) s=s or math.random(35,75); local c=200+s*4; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; NailMaker.nailMaker={name=n or ("Žebljar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žebljar najet: %s (spretnost: %d)",NailMaker.nailMaker.name,s),"success") end; return true end
function NailMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function NailMaker.build(id) local ok,e=NailMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(NailMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function NailMaker.getQualityBonus() local b=0; for _,bd in ipairs(NailMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function NailMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and NailMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.copperCost and NailMaker.copperStock<(d.copperCost or 0) then return false,"Premalo bakra" end; if #NailMaker.buildings==0 then return false,"Potrebna žebeljarna" end; if not NailMaker.nailMaker then return false,"Potreben žebljar" end; return true end
function NailMaker.make(pt) local ok,e=NailMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then NailMaker.ironStock=NailMaker.ironStock-d.ironCost end; if d.copperCost then NailMaker.copperStock=NailMaker.copperStock-d.copperCost end; local t=d.time; if NailMaker.nailMaker then t=math.max(1,t-math.floor(NailMaker.nailMaker.skill/15)) end; table.insert(NailMaker.activeMaking,{id="nail_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,quantity=d.quantity or 1,securityBonus=d.securityBonus or 0,prestige=d.prestige or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %s (%d dni)",d.name,t),"info") end; return true end
function NailMaker.completeMaking(m) local q=1.0+(NailMaker.getQualityBonus()/100); if NailMaker.nailMaker then q=q+(NailMaker.nailMaker.skill/200) end; q=math.min(2.0,q); NailMaker.productStock[m.productType]=(NailMaker.productStock[m.productType] or 0)+m.quantity; NailMaker.totalProducts=NailMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if NailMaker.nailMaker then NailMaker.nailMaker.itemsMade=NailMaker.nailMaker.itemsMade+m.quantity; if math.random()<0.15 then NailMaker.nailMaker.skill=math.min(100,NailMaker.nailMaker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function NailMaker.update(dt) if not _G.state then return end; NailMaker.dayTimer=NailMaker.dayTimer+dt; if NailMaker.dayTimer>=30 then NailMaker.dayTimer=0; for i=#NailMaker.activeMaking,1,-1 do local m=NailMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then NailMaker.completeMaking(m); table.remove(NailMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(NailMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if NailMaker.nailMaker then tu=tu+6 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function NailMaker.getStats() return {ironStock=NailMaker.ironStock,copperStock=NailMaker.copperStock,productStock=NailMaker.productStock,numBuildings=#NailMaker.buildings,hasNailMaker=NailMaker.nailMaker~=nil,nailMakerName=NailMaker.nailMaker and NailMaker.nailMaker.name or "—",nailMakerSkill=NailMaker.nailMaker and NailMaker.nailMaker.skill or 0,activeMaking=#NailMaker.activeMaking,totalProducts=NailMaker.totalProducts} end
return NailMaker
